+func waitForStartupReady(w waitCapturer, promptPattern string, timeout time.Duration) (string, error) {
+	if timeout <= 0 {
+		timeout = cursorStartupProbeWindow
+	}
+
+	deadline := time.Now().Add(timeout)
+	attempts := int(math.Ceil(float64(timeout) / float64(cursorStartupProbeWindow)))
+	if attempts < 1 {
+		attempts = 1
+	}
+
+	var lastErr error
+	for range attempts {
+		remaining := time.Until(deadline)
+		if remaining <= 0 {
+			break
+		}
+
+		probeWindow := minDuration(cursorStartupProbeWindow, remaining)
+		content, err := w.WaitFor(promptPattern, probeWindow)
+		if err != nil {
+			lastErr = err
+			continue
+		}
+
+		stableWindow := minDuration(cursorStartupStableWindow, time.Until(deadline))
+		if stableWindow <= 0 {
+			return content, nil
+		}
+		if _, err := w.WaitFor(promptPattern, stableWindow); err == nil {
+			return content, nil
+		} else {
+			lastErr = fmt.Errorf("prompt became unstable: %w", err)
+		}
+	}
+
